pub unsafe extern "system" fn HalpDmaGetDmaAlignment(AdapterObject: PADAPTER_OBJECT) -> u32 {
    1
}

#[no_mangle]
pub unsafe extern "system" fn HalReadDmaCounter(AdapterObject: PADAPTER_OBJECT) -> u32 {
    let mut OldIrql: KIRQL = 0;
    let mut Count: u32;
    let mut OldCount: u32;

    KeAcquireSpinLock(&mut (*(*AdapterObject).MasterAdapter).SpinLock, &mut OldIrql);

    if (*AdapterObject).AdapterNumber == 1 {
        let DmaControl1 = (*AdapterObject).AdapterBaseVa as *mut _DMA1_CONTROL;

        Count = 0xffff00;
        loop {
            OldCount = Count;

            WRITE_PORT_UCHAR(&mut (*DmaControl1).ClearBytePointer, 0);

            Count = READ_PORT_UCHAR(&(*DmaControl1).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount) as u32;
            Count |= (READ_PORT_UCHAR(&(*DmaControl1).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount) as u32) << 8;

            if (0xffff00 & (OldCount ^ Count)) == 0 {
                break;
            }
        }
    } else {
        let DmaControl2 = (*AdapterObject).AdapterBaseVa as *mut _DMA2_CONTROL;

        Count = 0xffff00;
        loop {
            OldCount = Count;

            WRITE_PORT_UCHAR(&mut (*DmaControl2).ClearBytePointer, 0);

            Count = READ_PORT_UCHAR(&(*DmaControl2).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount) as u32;
            Count |= (READ_PORT_UCHAR(&(*DmaControl2).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount) as u32) << 8;

            if (0xffff00 & (OldCount ^ Count)) == 0 {
                break;
            }
        }
    }

    KeReleaseSpinLock(&mut (*(*AdapterObject).MasterAdapter).SpinLock, OldIrql);

    Count = Count.wrapping_add(1);
    Count &= 0xffff;
    if (*AdapterObject).Width16Bits != 0 {
        Count = Count.wrapping_mul(2);
    }

    Count
}

unsafe fn HalpGrowMapBufferWorker(DeferredContext: *mut core::ffi::c_void) {
    let WorkItem: PGROW_WORK_ITEM = DeferredContext as PGROW_WORK_ITEM;
    let mut OldIrql: KIRQL;
    let Succeeded: u8;

    KeWaitForSingleObject(
        core::ptr::addr_of_mut!(HalpDmaLock) as *mut core::ffi::c_void,
        0,
        0,
        0u8,
        core::ptr::null_mut(),
    );
    Succeeded = HalpGrowMapBuffers(
        (*(*WorkItem).AdapterObject).MasterAdapter,
        (*WorkItem).NumberOfMapRegisters << PAGE_SHIFT,
    );
    KeSetEvent(
        core::ptr::addr_of_mut!(HalpDmaLock) as *mut core::ffi::c_void,
        0,
        0,
    );

    if Succeeded != 0 {
        OldIrql = KfRaiseIrql(DISPATCH_LEVEL);
        IoFreeMapRegisters((*WorkItem).AdapterObject, 2 as *mut core::ffi::c_void, 0);
        KfLowerIrql(OldIrql);
    }

    ExFreePool(WorkItem as *mut core::ffi::c_void);
}

#[no_mangle]
pub unsafe extern "system" fn HalAllocateAdapterChannel(
    AdapterObject: PADAPTER_OBJECT,
    WaitContextBlock: PWAIT_CONTEXT_BLOCK,
    NumberOfMapRegisters: ULONG,
    ExecutionRoutine: PDRIVER_CONTROL,
) -> NTSTATUS {
    let mut MasterAdapter: PADAPTER_OBJECT;
    let mut WorkItem: *mut GROW_WORK_ITEM;
    let mut Index: ULONG = MAXULONG;
    let Result: IO_ALLOCATION_ACTION;
    let mut OldIrql: KIRQL = 0;

    (*WaitContextBlock).DeviceRoutine = ExecutionRoutine;
    (*WaitContextBlock).NumberOfMapRegisters = NumberOfMapRegisters;

    if KeInsertDeviceQueue(
        core::ptr::addr_of_mut!((*AdapterObject).ChannelWaitQueue),
        core::ptr::addr_of_mut!((*WaitContextBlock).WaitQueueEntry),
    ) != 0
    {
        return STATUS_SUCCESS;
    }

    MasterAdapter = (*AdapterObject).MasterAdapter;

    (*AdapterObject).NumberOfMapRegisters = NumberOfMapRegisters;
    (*AdapterObject).CurrentWcb = WaitContextBlock;

    if (NumberOfMapRegisters != 0) && ((*AdapterObject).NeedsMapRegisters != 0) {
        if NumberOfMapRegisters > (*AdapterObject).MapRegistersPerChannel {
            (*AdapterObject).NumberOfMapRegisters = 0;
            IoFreeAdapterChannel(AdapterObject);
            return STATUS_INSUFFICIENT_RESOURCES;
        }

        KeAcquireSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), core::ptr::addr_of_mut!(OldIrql));

        if IsListEmpty(core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue)) != 0 {
            Index = RtlFindClearBitsAndSet((*MasterAdapter).MapRegisters, NumberOfMapRegisters, 0);
            if Index != MAXULONG {
                (*AdapterObject).MapRegisterBase = (*MasterAdapter).MapRegisterBase.offset(Index as isize);
                if (*AdapterObject).ScatterGather == 0 {
                    (*AdapterObject).MapRegisterBase = ((*AdapterObject).MapRegisterBase as ULONG_PTR | MAP_BASE_SW_SG) as PROS_MAP_REGISTER_ENTRY;
                }
            }
        }

        if Index == MAXULONG {
            InsertTailList(
                core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue),
                core::ptr::addr_of_mut!((*AdapterObject).AdapterQueue),
            );

            WorkItem = ExAllocatePoolWithTag(
                NonPagedPool,
                core::mem::size_of::<GROW_WORK_ITEM>() as SIZE_T,
                TAG_DMA,
            ) as *mut GROW_WORK_ITEM;
            if !WorkItem.is_null() {
                ExInitializeWorkItem(
                    core::ptr::addr_of_mut!((*WorkItem).WorkQueueItem),
                    Some(HalpGrowMapBufferWorker),
                    WorkItem as PVOID,
                );
                (*WorkItem).AdapterObject = AdapterObject;
                (*WorkItem).NumberOfMapRegisters = NumberOfMapRegisters;

                ExQueueWorkItem(
                    core::ptr::addr_of_mut!((*WorkItem).WorkQueueItem),
                    DelayedWorkQueue,
                );
            }

            KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);

            return STATUS_SUCCESS;
        }

        KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);
    } else {
        (*AdapterObject).MapRegisterBase = core::ptr::null_mut();
        (*AdapterObject).NumberOfMapRegisters = 0;
    }

    (*AdapterObject).CurrentWcb = WaitContextBlock;

    Result = ExecutionRoutine.unwrap()(
        (*WaitContextBlock).DeviceObject,
        (*WaitContextBlock).CurrentIrp,
        (*AdapterObject).MapRegisterBase as PVOID,
        (*WaitContextBlock).DeviceContext,
    );

    if Result == DeallocateObject {
        IoFreeAdapterChannel(AdapterObject);
    } else if Result == DeallocateObjectKeepRegisters {
        (*AdapterObject).NumberOfMapRegisters = 0;
        IoFreeAdapterChannel(AdapterObject);
    }

    STATUS_SUCCESS
}

#[no_mangle]
pub unsafe extern "system" fn IoFreeAdapterChannel(AdapterObject: PADAPTER_OBJECT) {
    let mut MasterAdapter: PADAPTER_OBJECT;
    let mut DeviceQueueEntry: PKDEVICE_QUEUE_ENTRY;
    let mut WaitContextBlock: PWAIT_CONTEXT_BLOCK;
    let mut Index: u32 = 0xFFFFFFFF;
    let mut Result: u32;
    let mut OldIrql: KIRQL;

    MasterAdapter = (*AdapterObject).MasterAdapter;

    loop {
        if (*AdapterObject).NumberOfMapRegisters != 0 {
            IoFreeMapRegisters(
                AdapterObject,
                (*AdapterObject).MapRegisterBase,
                (*AdapterObject).NumberOfMapRegisters,
            );
        }

        DeviceQueueEntry = KeRemoveDeviceQueue(core::ptr::addr_of_mut!((*AdapterObject).ChannelWaitQueue));
        if DeviceQueueEntry.is_null() {
            break;
        }

        WaitContextBlock = (DeviceQueueEntry as *mut u8).offset(
            -(core::mem::offset_of!(WAIT_CONTEXT_BLOCK, WaitQueueEntry) as isize)
        ) as PWAIT_CONTEXT_BLOCK;

        (*AdapterObject).CurrentWcb = WaitContextBlock;
        (*AdapterObject).NumberOfMapRegisters = (*WaitContextBlock).NumberOfMapRegisters;

        if ((*WaitContextBlock).NumberOfMapRegisters != 0) && (!(*AdapterObject).MasterAdapter.is_null()) {
            KeAcquireSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), core::ptr::addr_of_mut!(OldIrql));

            if IsListEmpty(core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue)) != 0 {
                Index = RtlFindClearBitsAndSet(
                    (*MasterAdapter).MapRegisters,
                    (*WaitContextBlock).NumberOfMapRegisters,
                    0,
                );
                if Index != 0xFFFFFFFF {
                    (*AdapterObject).MapRegisterBase = (*MasterAdapter).MapRegisterBase.offset(Index as isize);
                    if (*AdapterObject).ScatterGather == 0 {
                        (*AdapterObject).MapRegisterBase = ((*AdapterObject).MapRegisterBase as usize | 0x1) as *mut core::ffi::c_void;
                    }
                }
            }

            if Index == 0xFFFFFFFF {
                InsertTailList(
                    core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue),
                    core::ptr::addr_of_mut!((*AdapterObject).AdapterQueue),
                );
                KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);
                break;
            }

            KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);
        } else {
            (*AdapterObject).MapRegisterBase = core::ptr::null_mut();
            (*AdapterObject).NumberOfMapRegisters = 0;
        }

        Result = core::mem::transmute::<_, extern "system" fn(*mut core::ffi::c_void, *mut core::ffi::c_void, *mut core::ffi::c_void, *mut core::ffi::c_void) -> u32>(
            (*WaitContextBlock).DeviceRoutine
        )(
            (*WaitContextBlock).DeviceObject,
            (*WaitContextBlock).CurrentIrp,
            (*AdapterObject).MapRegisterBase,
            (*WaitContextBlock).DeviceContext,
        );

        match Result {
            0 => {
                return;
            }
            1 => {
                (*AdapterObject).NumberOfMapRegisters = 0;
            }
            _ => {}
        }
    }
}

#[no_mangle]
pub unsafe extern "system" fn IoFreeMapRegisters(
    AdapterObject: PADAPTER_OBJECT,
    MapRegisterBase: *mut core::ffi::c_void,
    NumberOfMapRegisters: u32,
) {
    let MasterAdapter: PADAPTER_OBJECT = (*AdapterObject).MasterAdapter;
    let mut ListEntry: PLIST_ENTRY;
    let mut OldIrql: KIRQL;
    let mut Index: u32;
    let mut Result: u32;
    let mut CurrentAdapterObject: PADAPTER_OBJECT;

    if MasterAdapter.is_null() || MapRegisterBase.is_null() {
        return;
    }

    KeAcquireSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), core::ptr::addr_of_mut!(OldIrql));

    if NumberOfMapRegisters != 0 {
        let RealMapRegisterBase: PROS_MAP_REGISTER_ENTRY;

        RealMapRegisterBase = (MapRegisterBase as usize & !MAP_BASE_SW_SG) as PROS_MAP_REGISTER_ENTRY;
        RtlClearBits(
            (*MasterAdapter).MapRegisters,
            (RealMapRegisterBase as usize - (*MasterAdapter).MapRegisterBase as usize) as u32 / core::mem::size_of::<ROS_MAP_REGISTER_ENTRY>() as u32,
            NumberOfMapRegisters,
        );
    }

    while IsListEmpty(core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue)) == 0 {
        ListEntry = RemoveHeadList(core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue));
        CurrentAdapterObject = (ListEntry as usize - core::mem::offset_of!(_ADAPTER_OBJECT, AdapterQueue)) as PADAPTER_OBJECT;

        Index = RtlFindClearBitsAndSet(
            (*MasterAdapter).MapRegisters,
            (*CurrentAdapterObject).NumberOfMapRegisters,
            0,
        );
        if Index == 0xFFFFFFFF {
            InsertHeadList(core::ptr::addr_of_mut!((*MasterAdapter).AdapterQueue), ListEntry);
            break;
        }

        KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);

        (*CurrentAdapterObject).MapRegisterBase = ((*MasterAdapter).MapRegisterBase as usize + Index as usize * core::mem::size_of::<ROS_MAP_REGISTER_ENTRY>()) as PROS_MAP_REGISTER_ENTRY;
        if (*CurrentAdapterObject).ScatterGather == 0 {
            (*CurrentAdapterObject).MapRegisterBase = ((*CurrentAdapterObject).MapRegisterBase as usize | MAP_BASE_SW_SG) as PROS_MAP_REGISTER_ENTRY;
        }

        Result = ((*(*CurrentAdapterObject).CurrentWcb).DeviceRoutine.unwrap())(
            (*(*CurrentAdapterObject).CurrentWcb).DeviceObject,
            (*(*CurrentAdapterObject).CurrentWcb).CurrentIrp,
            (*CurrentAdapterObject).MapRegisterBase as *mut core::ffi::c_void,
            (*(*CurrentAdapterObject).CurrentWcb).DeviceContext,
        );
        
        match Result {
            1 => {
                (*CurrentAdapterObject).NumberOfMapRegisters = 0;
                if (*CurrentAdapterObject).NumberOfMapRegisters != 0 {
                    KeAcquireSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), core::ptr::addr_of_mut!(OldIrql));
                    RtlClearBits(
                        (*MasterAdapter).MapRegisters,
                        (((*CurrentAdapterObject).MapRegisterBase as usize & !MAP_BASE_SW_SG) - (*MasterAdapter).MapRegisterBase as usize) as u32 / core::mem::size_of::<ROS_MAP_REGISTER_ENTRY>() as u32,
                        (*CurrentAdapterObject).NumberOfMapRegisters,
                    );
                    KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);
                }
                IoFreeAdapterChannel(CurrentAdapterObject);
            }
            2 => {
                if (*CurrentAdapterObject).NumberOfMapRegisters != 0 {
                    KeAcquireSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), core::ptr::addr_of_mut!(OldIrql));
                    RtlClearBits(
                        (*MasterAdapter).MapRegisters,
                        (((*CurrentAdapterObject).MapRegisterBase as usize & !MAP_BASE_SW_SG) - (*MasterAdapter).MapRegisterBase as usize) as u32 / core::mem::size_of::<ROS_MAP_REGISTER_ENTRY>() as u32,
                        (*CurrentAdapterObject).NumberOfMapRegisters,
                    );
                    KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);
                }
                IoFreeAdapterChannel(CurrentAdapterObject);
            }
            _ => {}
        }

        KeAcquireSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), core::ptr::addr_of_mut!(OldIrql));
    }

    KeReleaseSpinLock(core::ptr::addr_of_mut!((*MasterAdapter).SpinLock), OldIrql);
}

#[no_mangle]
pub unsafe extern "system" fn HalpCopyBufferMap(
    Mdl: PMDL,
    MapRegisterBase: PROS_MAP_REGISTER_ENTRY,
    CurrentVa: PVOID,
    Length: ULONG,
    WriteToDevice: BOOLEAN,
) {
    let mut CurrentLength: ULONG;
    let mut CurrentAddress: ULONG_PTR;
    let ByteOffset: ULONG;
    let VirtualAddress: PVOID;
    let mut MapRegisterBase = MapRegisterBase;
    let mut Length = Length;

    VirtualAddress = MmGetSystemAddressForMdlSafe(Mdl, HighPagePriority);
    if VirtualAddress.is_null() {
        KeBugCheckEx(HAL_MEMORY_ALLOCATION, PAGE_SIZE as ULONG_PTR, 0, b"dma.c\0".as_ptr() as ULONG_PTR, 0);
    }

    CurrentAddress = VirtualAddress as ULONG_PTR +
                     CurrentVa as ULONG_PTR -
                     MmGetMdlVirtualAddress(Mdl) as ULONG_PTR;

    while Length > 0 {
        ByteOffset = BYTE_OFFSET(CurrentAddress);
        CurrentLength = PAGE_SIZE - ByteOffset;
        if CurrentLength > Length {
            CurrentLength = Length;
        }

        if WriteToDevice != 0 {
            RtlCopyMemory(
                ((*MapRegisterBase).VirtualAddress as ULONG_PTR + ByteOffset as ULONG_PTR) as PVOID,
                CurrentAddress as PVOID,
                CurrentLength as usize,
            );
        } else {
            RtlCopyMemory(
                CurrentAddress as PVOID,
                ((*MapRegisterBase).VirtualAddress as ULONG_PTR + ByteOffset as ULONG_PTR) as PVOID,
                CurrentLength as usize,
            );
        }

        Length -= CurrentLength;
        CurrentAddress += CurrentLength as ULONG_PTR;
        MapRegisterBase = MapRegisterBase.offset(1);
    }
}

#[no_mangle]
pub unsafe extern "system" fn IoFlushAdapterBuffers(
    AdapterObject: PADAPTER_OBJECT,
    Mdl: PMDL,
    MapRegisterBase: PVOID,
    CurrentVa: PVOID,
    Length: ULONG,
    WriteToDevice: BOOLEAN,
) -> BOOLEAN {
    let mut SlaveDma: BOOLEAN = 0u8;
    let RealMapRegisterBase: PROS_MAP_REGISTER_ENTRY;
    let HighestAcceptableAddress: PHYSICAL_ADDRESS;
    let mut PhysicalAddress: PHYSICAL_ADDRESS = core::mem::zeroed();
    let MdlPagesPtr: PPFN_NUMBER;

    ASSERT_IRQL_LESS_OR_EQUAL(DISPATCH_LEVEL);
    ASSERT(AdapterObject);

    if (*AdapterObject).MasterDevice == 0 {
        if (*AdapterObject).AdapterNumber == 1 {
            let DmaControl1 = (*AdapterObject).AdapterBaseVa as PDMA1_CONTROL;
            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl1).SingleMask),
                (*AdapterObject).ChannelNumber | DMA_SETMASK,
            );
        } else {
            let DmaControl2 = (*AdapterObject).AdapterBaseVa as PDMA2_CONTROL;
            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl2).SingleMask),
                (*AdapterObject).ChannelNumber | DMA_SETMASK,
            );
        }
        SlaveDma = 1u8;
    }

    if MapRegisterBase == core::ptr::null_mut() {
        return 1u8;
    }

    RealMapRegisterBase = ((MapRegisterBase as ULONG_PTR) & !MAP_BASE_SW_SG) as PROS_MAP_REGISTER_ENTRY;

    if WriteToDevice == 0 {
        if ((MapRegisterBase as ULONG_PTR) & MAP_BASE_SW_SG) != 0 {
            if (*RealMapRegisterBase).Counter != MAXULONG {
                if (SlaveDma != 0) && ((*AdapterObject).IgnoreCount == 0) {
                    Length = Length - HalReadDmaCounter(AdapterObject);
                }
            }
            HalpCopyBufferMap(Mdl, RealMapRegisterBase, CurrentVa, Length, 0u8);
        } else {
            let mut MdlPagesPtr = MmGetMdlPfnArray(Mdl);
            MdlPagesPtr = MdlPagesPtr.offset(
                (((CurrentVa as ULONG_PTR) - ((*Mdl).StartVa as ULONG_PTR)) >> PAGE_SHIFT) as isize
            );

            PhysicalAddress.QuadPart = (*MdlPagesPtr as i64) << PAGE_SHIFT;
            PhysicalAddress.QuadPart += BYTE_OFFSET(CurrentVa) as i64;

            HighestAcceptableAddress = HalpGetAdapterMaximumPhysicalAddress(AdapterObject);
            if (PhysicalAddress.QuadPart + Length as i64) > HighestAcceptableAddress.QuadPart {
                HalpCopyBufferMap(Mdl, RealMapRegisterBase, CurrentVa, Length, 0u8);
            }
        }
    }

    (*RealMapRegisterBase).Counter = 0;

    1u8
}

#[no_mangle]
pub unsafe extern "system" fn IoMapTransfer(
    AdapterObject: PADAPTER_OBJECT,
    Mdl: PMDL,
    MapRegisterBase: PVOID,
    CurrentVa: PVOID,
    Length: PULONG,
    WriteToDevice: BOOLEAN,
) -> PHYSICAL_ADDRESS {
    let mut MdlPagesPtr: PPFN_NUMBER;
    let MdlPage1: PFN_NUMBER;
    let MdlPage2: PFN_NUMBER;
    let ByteOffset: ULONG;
    let mut TransferOffset: ULONG;
    let mut TransferLength: ULONG;
    let mut UseMapRegisters: BOOLEAN;
    let RealMapRegisterBase: PROS_MAP_REGISTER_ENTRY;
    let mut PhysicalAddress: PHYSICAL_ADDRESS = core::mem::zeroed();
    let HighestAcceptableAddress: PHYSICAL_ADDRESS;
    let mut Counter: ULONG;
    let mut AdapterMode: DMA_MODE;
    let mut OldIrql: KIRQL = 0;

    ByteOffset = BYTE_OFFSET(CurrentVa);

    MdlPagesPtr = MmGetMdlPfnArray(Mdl);
    MdlPagesPtr = MdlPagesPtr.offset((((CurrentVa as ULONG_PTR) - ((*Mdl).StartVa as ULONG_PTR)) >> PAGE_SHIFT) as isize);

    PhysicalAddress.QuadPart = (*MdlPagesPtr as i64) << PAGE_SHIFT;
    PhysicalAddress.QuadPart += ByteOffset as i64;

    TransferLength = PAGE_SIZE - ByteOffset;

    if MapRegisterBase == core::ptr::null_mut() {
        while TransferLength < *Length {
            MdlPage1 = *MdlPagesPtr;
            MdlPage2 = *(MdlPagesPtr.offset(1));
            if MdlPage1 + 1 != MdlPage2 {
                break;
            }
            if (MdlPage1 ^ MdlPage2) & !0xFFFFF != 0 {
                break;
            }
            TransferLength += PAGE_SIZE;
            MdlPagesPtr = MdlPagesPtr.offset(1);
        }

        if TransferLength < *Length {
            *Length = TransferLength;
        }

        return PhysicalAddress;
    }

    RealMapRegisterBase = ((MapRegisterBase as ULONG_PTR) & !MAP_BASE_SW_SG) as PROS_MAP_REGISTER_ENTRY;

    while TransferLength < *Length {
        MdlPage1 = *MdlPagesPtr;
        MdlPage2 = *(MdlPagesPtr.offset(1));
        if MdlPage1 + 1 != MdlPage2 {
            break;
        }
        if HalpEisaDma == 0 && ((MdlPage1 ^ MdlPage2) & !0xF) != 0 {
            break;
        }
        TransferLength += PAGE_SIZE;
        MdlPagesPtr = MdlPagesPtr.offset(1);
    }

    if TransferLength > *Length {
        TransferLength = *Length;
    }

    if ((MapRegisterBase as ULONG_PTR) & MAP_BASE_SW_SG) != 0 && TransferLength < *Length {
        UseMapRegisters = 1u8;
        PhysicalAddress = (*RealMapRegisterBase).PhysicalAddress;
        PhysicalAddress.QuadPart += ByteOffset as i64;
        TransferLength = *Length;
        (*RealMapRegisterBase).Counter = MAXULONG;
        Counter = 0;
    } else {
        UseMapRegisters = 0u8;
        Counter = (*RealMapRegisterBase).Counter;
        (*RealMapRegisterBase).Counter += BYTES_TO_PAGES(ByteOffset + TransferLength);

        HighestAcceptableAddress = HalpGetAdapterMaximumPhysicalAddress(AdapterObject);
        if (PhysicalAddress.QuadPart + TransferLength as i64) > HighestAcceptableAddress.QuadPart {
            UseMapRegisters = 1u8;
            PhysicalAddress = (*RealMapRegisterBase.offset(Counter as isize)).PhysicalAddress;
            PhysicalAddress.QuadPart += ByteOffset as i64;
            if ((MapRegisterBase as ULONG_PTR) & MAP_BASE_SW_SG) != 0 {
                (*RealMapRegisterBase).Counter = MAXULONG;
                Counter = 0;
            }
        }
    }

    if UseMapRegisters != 0 && WriteToDevice != 0 {
        HalpCopyBufferMap(
            Mdl,
            RealMapRegisterBase.offset(Counter as isize),
            CurrentVa,
            TransferLength,
            WriteToDevice,
        );
    }

    *Length = TransferLength;

    if !AdapterObject.is_null() && (*AdapterObject).MasterDevice == 0 {
        AdapterMode = (*AdapterObject).AdapterMode;

        if WriteToDevice != 0 {
            AdapterMode.TransferType = WRITE_TRANSFER;
        } else {
            AdapterMode.TransferType = READ_TRANSFER;
            if (*AdapterObject).IgnoreCount != 0 {
                RtlZeroMemory(
                    ((*RealMapRegisterBase.offset(Counter as isize)).VirtualAddress as PUCHAR).offset(ByteOffset as isize) as PVOID,
                    TransferLength as SIZE_T,
                );
            }
        }

        TransferOffset = PhysicalAddress.__bindgen_anon_1.LowPart & 0xFFFF;
        if (*AdapterObject).Width16Bits != 0 {
            TransferLength >>= 1;
            TransferOffset >>= 1;
        }

        KeAcquireSpinLock(
            core::ptr::addr_of_mut!((*(*AdapterObject).MasterAdapter).SpinLock),
            core::ptr::addr_of_mut!(OldIrql),
        );

        if (*AdapterObject).AdapterNumber == 1 {
            let DmaControl1: PDMA1_CONTROL = (*AdapterObject).AdapterBaseVa as PDMA1_CONTROL;

            WRITE_PORT_UCHAR(core::ptr::addr_of_mut!((*DmaControl1).ClearBytePointer), 0);

            WRITE_PORT_UCHAR(core::ptr::addr_of_mut!((*DmaControl1).Mode), AdapterMode.Byte);

            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl1).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseAddress),
                (TransferOffset) as UCHAR,
            );
            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl1).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseAddress),
                (TransferOffset >> 8) as UCHAR,
            );

            WRITE_PORT_UCHAR(
                ((*AdapterObject).PagePort as *mut u8).offset(FIELD_OFFSET(EISA_CONTROL, DmaController1Pages) as isize),
                (PhysicalAddress.__bindgen_anon_1.LowPart >> 16) as UCHAR,
            );
            if HalpEisaDma != 0 {
                WRITE_PORT_UCHAR(
                    ((*AdapterObject).PagePort as *mut u8).offset(FIELD_OFFSET(EISA_CONTROL, DmaController2Pages) as isize),
                    0,
                );
            }

            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl1).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount),
                (TransferLength - 1) as UCHAR,
            );
            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl1).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount),
                ((TransferLength - 1) >> 8) as UCHAR,
            );

            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl1).SingleMask),
                (*AdapterObject).ChannelNumber | DMA_CLEARMASK,
            );
        } else {
            let DmaControl2: PDMA2_CONTROL = (*AdapterObject).AdapterBaseVa as PDMA2_CONTROL;

            WRITE_PORT_UCHAR(core::ptr::addr_of_mut!((*DmaControl2).ClearBytePointer), 0);

            WRITE_PORT_UCHAR(core::ptr::addr_of_mut!((*DmaControl2).Mode), AdapterMode.Byte);

            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl2).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseAddress),
                (TransferOffset) as UCHAR,
            );
            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl2).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseAddress),
                (TransferOffset >> 8) as UCHAR,
            );

            WRITE_PORT_UCHAR(
                ((*AdapterObject).PagePort as *mut u8).offset(FIELD_OFFSET(EISA_CONTROL, DmaController1Pages) as isize),
                ((*PhysicalAddress.u.__bindgen_anon_1.LowPart()) >> 16) as UCHAR,
            );
            if HalpEisaDma != 0 {
                WRITE_PORT_UCHAR(
                    ((*AdapterObject).PagePort as *mut u8).offset(FIELD_OFFSET(EISA_CONTROL, DmaController2Pages) as isize),
                    0,
                );
            }

            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl2).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount),
                (TransferLength - 1) as UCHAR,
            );
            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl2).DmaAddressCount[(*AdapterObject).ChannelNumber as usize].DmaBaseCount),
                ((TransferLength - 1) >> 8) as UCHAR,
            );

            WRITE_PORT_UCHAR(
                core::ptr::addr_of_mut!((*DmaControl2).SingleMask),
                (*AdapterObject).ChannelNumber | DMA_CLEARMASK,
            );
        }

        KeReleaseSpinLock(
            core::ptr::addr_of_mut!((*(*AdapterObject).MasterAdapter).SpinLock),
            OldIrql,
        );
    }

    PhysicalAddress
}

#[no_mangle]
pub unsafe extern "system" fn HalFlushCommonBuffer(
    AdapterObject: PADAPTER_OBJECT,
    Length: ULONG,
    LogicalAddress: PHYSICAL_ADDRESS,
    VirtualAddress: PVOID,
) -> BOOLEAN {
    1u8
}

#[no_mangle]
pub unsafe extern "system" fn HalAllocateCrashDumpRegisters(
    AdapterObject: PADAPTER_OBJECT,
    NumberOfMapRegisters: PULONG,
) -> PVOID {
    let MasterAdapter = (*AdapterObject).MasterAdapter;
    let mut MapRegisterNumber: ULONG;

    if (*AdapterObject).NeedsMapRegisters != 0 {
        if *NumberOfMapRegisters > (*AdapterObject).MapRegistersPerChannel {
            (*AdapterObject).NumberOfMapRegisters = 0;
            return core::ptr::null_mut();
        }

        MapRegisterNumber = RtlFindClearBitsAndSet(
            (*MasterAdapter).MapRegisters,
            *NumberOfMapRegisters,
            0,
        );

        if MapRegisterNumber == MAXULONG {
            RtlSetBits(
                (*MasterAdapter).MapRegisters,
                0,
                *NumberOfMapRegisters,
            );
            MapRegisterNumber = 0;
        }

        (*AdapterObject).MapRegisterBase = ((*MasterAdapter).MapRegisterBase as usize
            + MapRegisterNumber as usize) as PROS_MAP_REGISTER_ENTRY;

        if (*AdapterObject).ScatterGather == 0 {
            (*AdapterObject).MapRegisterBase = (((*AdapterObject).MapRegisterBase as ULONG_PTR)
                | MAP_BASE_SW_SG) as PROS_MAP_REGISTER_ENTRY;
        }
    } else {
        (*AdapterObject).MapRegisterBase = core::ptr::null_mut();
        (*AdapterObject).NumberOfMapRegisters = 0;
    }

    (*AdapterObject).MapRegisterBase as PVOID
}
